import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { doctorAPI } from "../services/api";

export default function PatientsPage() {
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [filter, setFilter] = useState("all");

  useEffect(() => {
    doctorAPI.patients()
      .then(({ data }) => setRecords(data.records))
      .catch(() => setError("Failed to load patient records"))
      .finally(() => setLoading(false));
  }, []);

  const displayed = filter === "all" ? records : records.filter(r => r.predictionResult === (filter === "likely" ? "Likely" : "Not Likely"));

  if (loading) return <div className="loading-screen"><span className="spinner"></span></div>;

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
          <h1 style={{ fontSize: "1.5rem", fontWeight: 700 }}>Patient Records</h1>
          <div style={{ display: "flex", gap: ".5rem" }}>
            {["all","likely","not-likely"].map(f => (
              <button key={f} className={`btn btn-sm ${filter === f ? "btn-primary" : "btn-outline"}`} onClick={() => setFilter(f)}>
                {f === "all" ? "All" : f === "likely" ? "⚠️ High Risk" : "✅ Low Risk"}
              </button>
            ))}
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        <div className="card">
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Patient</th><th>Email</th><th>Result</th><th>Risk %</th>
                  <th>Age</th><th>BMI</th><th>Glucose</th><th>Date</th>
                </tr>
              </thead>
              <tbody>
                {displayed.length === 0 ? (
                  <tr><td colSpan={8} style={{ textAlign: "center", color: "var(--text-muted)" }}>No records found.</td></tr>
                ) : displayed.map((r) => (
                  <tr key={r._id}>
                    <td><strong>{r.patientId?.name || "—"}</strong></td>
                    <td>{r.patientId?.email || "—"}</td>
                    <td><span className={`badge ${r.predictionResult === "Likely" ? "badge-danger" : "badge-success"}`}>{r.predictionResult}</span></td>
                    <td>{r.riskProbability}%</td>
                    <td>{r.age}</td>
                    <td>{r.bmi}</td>
                    <td>{r.avgGlucoseLevel}</td>
                    <td>{new Date(r.createdAt).toLocaleDateString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
}
